<script setup lang="ts">
import { ref } from 'vue'
import { useVoiceStore } from '@stores/useVoiceStore'
import { t } from '@/i18n'

const voiceStore = useVoiceStore()
const draft = ref('')
const sendError = ref('')

function sendMessage() {
  const input = draft.value.trim()
  if (!input) return
  const command = input.startsWith('/')
  const content = command ? input.slice(1).trim() : input
  if (!content || !voiceStore.sendChatMessage(content, command)) {
    sendError.value = t('chat.notConnected')
    return
  }
  draft.value = ''
  sendError.value = ''
}
</script>

<template>
  <section class="chat-panel" :aria-label="t('chat.title')">
    <header>
      <div><h2>{{ t('chat.title') }}</h2><p>{{ t('chat.subtitle') }}</p></div>
      <strong :class="{ online: voiceStore.chatConnected }">
        {{ voiceStore.chatConnected ? t('chat.online') : t('chat.offline') }}
      </strong>
    </header>
    <ol class="messages" aria-live="polite">
      <li v-if="!voiceStore.chatMessages.length" class="empty">{{ t('chat.empty') }}</li>
      <li v-for="entry in voiceStore.chatMessages" :key="entry.id" :class="{ system: entry.system }">
        <time>{{ new Date(entry.receivedAt).toLocaleTimeString() }}</time>
        <template v-if="entry.playerName"><b>{{ entry.playerName }}</b><span>:</span></template>
        <span class="message">{{ entry.message }}</span>
      </li>
    </ol>
    <form class="composer" @submit.prevent="sendMessage">
      <label class="sr-only" for="chat-message">{{ t('chat.label') }}</label>
      <input id="chat-message" v-model="draft" maxlength="256" autocomplete="off" :placeholder="t('chat.placeholder')" />
      <button type="submit" :disabled="!voiceStore.chatConnected || !draft.trim()">{{ t('chat.send') }}</button>
    </form>
    <p v-if="sendError" class="send-error" role="alert">{{ sendError }}</p>
  </section>
</template>

