<script setup lang="ts">
import { computed } from 'vue'
import { useVoiceStore } from '@stores/useVoiceStore'
import { t } from '@/i18n'

const voiceStore = useVoiceStore()

const connectedPeers = computed(() => voiceStore.connectedPeers)
const localUserId = computed(() => voiceStore.state.localStream ? 'local' : '')

function formatVolume(volume: number): string {
  return `${Math.round(volume * 100)}%`
}

/** Per player volume, the way OpenAudioMc lets you mix the room. */
function setPeerVolume(peerId: string, event: Event) {
  const target = event.target as HTMLInputElement | null
  const value = target?.valueAsNumber
  if (value === undefined) return
  voiceStore.setPeerVolume(peerId, value)
}

</script>

